<?php
namespace App\Http\Controllers\Admin;use App\Enums\ManagementPermission;use App\Http\Controllers\Controller;use App\Models\AuditLog;use Illuminate\Http\Request;use Illuminate\Support\Facades\Gate;use Inertia\Inertia;use Inertia\Response;
class AuditController extends Controller {public function __invoke(Request $request):Response{Gate::authorize(ManagementPermission::AUDIT_VIEW->value);$logs=AuditLog::with('user:id,name')->when($request->filled('event'),fn($q)=>$q->where('event',$request->string('event')))->when($request->filled('date_from'),fn($q)=>$q->whereDate('occurred_at','>=',$request->date('date_from')))->when($request->filled('date_to'),fn($q)=>$q->whereDate('occurred_at','<=',$request->date('date_to')))->latest('occurred_at')->paginate(30)->withQueryString();return Inertia::render('Admin/Audit/Index',['logs'=>$logs,'events'=>AuditLog::distinct()->orderBy('event')->pluck('event'),'filters'=>$request->only(['event','date_from','date_to'])]);}}
